65	
66	  // Order block check IDs by GATE_CHECKS order
67	  const orderedBlockIds = GATE_CHECKS.filter((check) =>
68	    blockCheckIds.has(check.id)
69	  ).map((check) => check.id);
70	
71	  // Format the summary line
72	  const blocksPart = orderedBlockIds.length > 0 ? `: ${orderedBlockIds.join(', ')}` : '';
73	  return `${result.verdict} ${answered}/7${blocksPart}`;
74	}
