16	    branches: [main]
17	jobs:
18	  rai-gate:
19	    runs-on: ubuntu-latest
20	    steps:
21	      - uses: actions/checkout@v4
22	      - uses: actions/setup-node@v4
23	        with:
24	          node-version: '20'
25	      # Blocks the build until every Responsible AI Gate check in the spec is answered.
26	      - run: npx frai-gate check FRAI-SPEC.md
27	`;
28	
29	const HELP = `frai-gate - the FRAI Gate: a Responsible AI Gate for specs
30	
31	Usage:
32	  frai-gate init [--out <file>] [--ci]   Drop the RAI spec template into the repo (default: FRAI-SPEC.md);
33	                                         --ci also writes .github/workflows/rai-gate.yml so the gate
34	                                         runs on every PR
35	  frai-gate check <spec.md> [options]    Validate the spec's Responsible AI Gate
36	      --smart                            Add an AI quality review of the gate answers (Claude Agent SDK)
37	      --json                             Machine-readable output
38	      --summary                          Print a compact one-line summary instead of full report
39	  frai-gate draft [--out <file>] [--print]
40	                                         Scan this repo with a read-only agent and draft a filled-in
41	                                         gate section grounded in the code (default out: rai-gate-draft.md)
42	
43	Exit codes: 0 = PASS/WARN, 1 = BLOCK, 2 = usage/error.
44	The smart commands (draft, check --smart) use the Claude Agent SDK and need Claude Code
45	authentication or ANTHROPIC_API_KEY. Model override: FRAI_GATE_MODEL (default claude-opus-5).`;
46	
47	interface Args {
48	  command: string | undefined;
49	  positional: string[];
50	  flags: Map<string, string | true>;
