48	export function renderSummary(result: GateResult): string {
49	  // Special case: if gate section is missing and structure finding exists
50	  const structureFind = result.findings.find((f) => f.checkId === 'structure');
51	  if (result.gateSection === null && structureFind) {
52	    return 'BLOCK 0/7: structure';
53	  }
54	
55	  // Get all block findings' check IDs
56	  const blockCheckIds = new Set<string>();
57	  for (const finding of result.findings) {
58	    if (finding.severity === 'block') {
59	      blockCheckIds.add(finding.checkId);
60	    }
61	  }
62	
63	  // Count answered checks: if gate section is null, 0 answered; otherwise 7 - block_count
64	  const answered = result.gateSection === null ? 0 : 7 - blockCheckIds.size;
65	
66	  // Order block check IDs by GATE_CHECKS order
67	  const orderedBlockIds = GATE_CHECKS.filter((check) =>
68	    blockCheckIds.has(check.id)
69	  ).map((check) => check.id);
70	
71	  // Format the summary line
72	  const blocksPart = orderedBlockIds.length > 0 ? `: ${orderedBlockIds.join(', ')}` : '';
73	  return `${result.verdict} ${answered}/7${blocksPart}`;
74	}
